from __future__ import annotations

from typing import Optional
from uuid import UUID


class ExternalIdentifierConflict(ValueError):
    pass


def _uuid(value: Optional[str]) -> Optional[str]:
    if value is None:
        return None
    try:
        return str(UUID(str(value)))
    except (ValueError, TypeError, AttributeError) as exc:
        raise ValueError("UUID canonico invalido") from exc


def ensure_external_identifier(cursor, *, sistema_tipo_id: int, tipo_identificador: str, valor_externo: str, unidad_negocio_id: Optional[str] = None, sistema_version_id: Optional[str] = None, conexion_id: Optional[str] = None) -> int:
    tipo = str(tipo_identificador or "").strip()[:80]
    valor = str(valor_externo or "").strip()[:300]
    if not tipo or not valor:
        raise ValueError("TipoIdentificador y ValorExterno son requeridos")
    unidad = _uuid(unidad_negocio_id)
    version = _uuid(sistema_version_id)
    conexion = _uuid(conexion_id)
    cursor.execute("SELECT IdentificadorExternoID, UnidadNegocioID, SistemaVersionID, ConexionID FROM dbo.Sistema_IdentificadoresExternos WITH (UPDLOCK, HOLDLOCK) WHERE SistemaTipoID=%s AND TipoIdentificador=%s AND ValorExterno=%s", (int(sistema_tipo_id), tipo, valor))
    row = cursor.fetchone()
    if row:
        existing = tuple(str(x).lower() if x is not None else None for x in row[1:4])
        requested = tuple(x.lower() if x is not None else None for x in (unidad, version, conexion))
        if existing != requested:
            raise ExternalIdentifierConflict("Identificador externo ya ligado a otro scope canonico")
        return int(row[0])
    cursor.execute("INSERT INTO dbo.Sistema_IdentificadoresExternos (UnidadNegocioID,SistemaTipoID,SistemaVersionID,ConexionID,TipoIdentificador,ValorExterno,Activo,FechaAlta) OUTPUT INSERTED.IdentificadorExternoID VALUES (%s,%s,%s,%s,%s,%s,1,SYSUTCDATETIME())", (unidad, int(sistema_tipo_id), version, conexion, tipo, valor))
    inserted = cursor.fetchone()
    if not inserted:
        raise RuntimeError("No se pudo materializar identificador externo")
    return int(inserted[0])
